import{z as i,x as s,o as e,c as d,q as l,j as r,D as A,d as B,s as n,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"模型合并作为持续学习","description":"","frontmatter":{"title":"模型合并作为持续学习","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-model-merge.md","filePath":"llm/continual-model-merge.md","lastUpdated":1791063341000}'),p={name:"llm/continual-model-merge.md"};function m(D,E,h,u,_,C){const t=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=l('<h1 id="模型合并作为持续学习" tabindex="-1">模型合并作为持续学习 <a class="header-anchor" href="#模型合并作为持续学习" aria-label="Permalink to &quot;模型合并作为持续学习&quot;">​</a></h1><div class="epigraph"><p>把每个阶段学到的不是一段历史，而是一个向量；合并把「按顺序训」换成「把向量加起来」，绕开了覆盖问题本身。</p><footer>—— 据 Ilharco 等 2023（任务向量算术）、Yadav 等 2023（TIES-Merging）整理</footer></div><p><a href="/llm/continual-lora-lifecycle">上一课</a>把增量装进低秩模块里隔离管理；合并走另一条路：允许各阶段各自完整地微调出快照，再把权重组合成一个模型。主干<a href="/llm/model-merging">模型合并：SLERP / TIES / DARE</a>已把算法讲透，<a href="/llm/task-arithmetic">任务向量算术</a>给了「微调差值即任务」的视角；本课只补持续学习那一层：用合并代替按序列训练，换掉了什么、绕不过什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>序列微调的遗忘来自覆盖：\\(\\theta\\) 只有一份，后一个任务在前一个任务的解上继续走。合并的前提是解不止一份——每个阶段从同一基座各自训出快照 \\(\\theta_t\\)，互不覆盖。剩下的是组合问题：逐点平均在方向冲突的坐标上互相抵消，多向量叠加时退化更快。合并作为持续学习方法，核心是回答「哪些坐标可信、冲突听谁的」。</p><p><span class="marginnote">可以把任务向量想象成「这次微调在基座上走的位移」：起点固定在预训练模型，终点在微调后的模型，这支箭头本身就被当作「这个任务学到的全部」。两支箭头方向一致就能叠加增强，方向相反就会在同一个坐标上打架。</span></p><h3 id="任务向量与三类操作" tabindex="-1">任务向量与三类操作 <a class="header-anchor" href="#任务向量与三类操作" aria-label="Permalink to &quot;任务向量与三类操作&quot;">​</a></h3><p>定义 \\(\\tau_t=\\theta_t-\\theta_0\\)。任务算术给出三种语义：加 \\(\\tau\\) 注入能力，减 \\(\\tau\\) 摘除能力，加权组合折中。TIES-Merging（Yadav 等 2023）针对多向量叠加的三步：先按幅度裁掉小幅坐标（多数是微调噪声），再对余下坐标按总幅度投票定符号，最后只平均同号坐标——冲突不再互相抵消，而是被裁决。DARE（Yu 等 2023）用随机丢弃加重缩放达到类似的稀疏化效果。合并的持续学习用法由此成型：流上每隔一段训出快照，维护一串向量，周期性做一次 TIES 式合成，替换线上模型。</p><p><span class="marginnote">模型汤（Wortsman 等 2022）是同一思想的单任务版：把同一训练轨迹上不同超参的检查点贪心平均，常优于任一单点。持续学习里的轨迹平均——定期把近期快照平均一次——兼有抗漂移与平滑更新的作用，EMA 是它的在线特例。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上先做对簿记：每份快照绑基座版本、数据配方与评测成绩；向量是差值，基座一动全部作废，基座版本必须冻结或整批重算。合成节奏是第二个决策：太快，单段漂移没被平均掉；太慢，新能力上线延迟。按「每累积 \\(N\\) 个快照或探针变化超阈值」触发，比按日历稳。</p><p>验收比合并本身重要：合成后的模型要在<strong>全部构成任务</strong>上重过探针，而非只测最近任务。合并可能同时带来增益与亏空，亏空不在输入端暴露——只有全量回归知道这刀切对了没有。</p>',12)),(e(),r(o,null,{default:A(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SNAP%5B%22%E9%98%B6%E6%AE%B5%E5%BF%AB%E7%85%A7%20%CE%B8_t%22%5D%20--%3E%20VEC%5B%22%E5%B7%AE%E5%80%BC%E5%90%91%E9%87%8F%20%CF%84_t%3D%CE%B8_t-%CE%B8_0%22%5D%0A%20%20VEC%20--%3E%20TRIM%5B%22%E5%B9%85%E5%BA%A6%E8%A3%81%E5%89%AA%EF%BC%9A%E5%8E%BB%E5%99%AA%E5%A3%B0%E5%9D%90%E6%A0%87%22%5D%0A%20%20TRIM%20--%3E%20SIGN%5B%22%E7%AC%A6%E5%8F%B7%E6%8A%95%E7%A5%A8%EF%BC%9A%E5%86%B2%E7%AA%81%E5%9D%90%E6%A0%87%E8%A3%81%E5%86%B3%22%5D%0A%20%20SIGN%20--%3E%20AVG%5B%22%E5%90%8C%E5%8F%B7%E5%9D%90%E6%A0%87%E5%B9%B3%E5%9D%87%22%5D%0A%20%20AVG%20--%3E%20OUT%5B%22%E5%90%88%E6%88%90%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20OUT%20--%3E%20GATE%7B%22%E5%85%A8%E9%83%A8%E6%9E%84%E6%88%90%E4%BB%BB%E5%8A%A1%E6%8E%A2%E9%92%88%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20GATE%20--%3E%7C%E5%90%A6%7C%20ADJ%5B%22%E8%B0%83%E7%B3%BB%E6%95%B0%E6%88%96%E5%9B%9E%E9%80%80%E4%B8%8A%E7%89%88%22%5D%0A%20%20GATE%20--%3E%7C%E6%98%AF%7C%20SHIP%5B%22%E4%B8%8A%E7%BA%BF%EF%BC%8C%E7%99%BB%E8%AE%B0%E7%B0%BF%E8%AE%B0%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"合并为什么能绕开覆盖：各快照共享预训练解 \\(\\theta_0\\)，差值只编码「相对基座改了什么」，公共能力留在基座里，干涉只发生在各自改动的坐标上。幅度裁剪进一步压缩干涉面——微调改动的坐标本就稀疏，大幅坐标才是能力载体。符号裁决把同坐标上的方向冲突从数值抵消变成显式取舍，这是 TIES 相对朴素平均的全部增量。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"用数字感受一下裁剪：一个 7B 模型有约 70 亿个权重坐标，微调真正「用力」改动的往往只是其中一小撮；把改动幅度最小的多数坐标直接清零，既删掉了噪声，又让剩下的少数「真改动」在求平均时不被稀释。")],-1)),E[6]||(E[6]=a("p",null,"两种路线的差别可以画在同一张图里看：序列训练是「在上一份解上继续改写」，合并是「各写各的副本再合成」。",-1)),(e(),r(o,null,{default:A(()=>[n(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20SEQ%5B%22%E6%8C%89%E5%BA%8F%E5%88%97%E8%AE%AD%E7%BB%83%22%5D%0A%20%20%20%20A%5B%22%E5%9F%BA%E5%BA%A7%20%CE%B80%22%5D%20--%3E%20B%5B%22%E8%AE%AD%E5%AE%8C%E4%BB%BB%E5%8A%A11%E5%BE%97%20%CE%B81%22%5D%20--%3E%20C%5B%22%E5%9C%A8%20%CE%B81%20%E4%B8%8A%E6%8E%A5%E7%9D%80%E8%AE%AD%E4%BB%BB%E5%8A%A12%22%5D%20--%3E%20D%5B%22%CE%B82%3A%E4%BB%BB%E5%8A%A11%E7%9A%84%E8%A7%A3%E8%A2%AB%E8%A6%86%E7%9B%96%22%5D%0A%20%20end%0A%20%20subgraph%20MER%5B%22%E5%85%88%E5%BF%AB%E7%85%A7%E5%86%8D%E5%90%88%E5%B9%B6%22%5D%0A%20%20%20%20E%5B%22%E5%9F%BA%E5%BA%A7%20%CE%B80%22%5D%20--%3E%20F%5B%22%E5%BF%AB%E7%85%A71%3A%E5%8F%AA%E5%AD%A6%E4%BB%BB%E5%8A%A11%22%5D%0A%20%20%20%20E%20--%3E%20G%5B%22%E5%BF%AB%E7%85%A72%3A%E5%8F%AA%E5%AD%A6%E4%BB%BB%E5%8A%A12%22%5D%0A%20%20%20%20F%20--%3E%20H%5B%22TIES%20%E5%90%88%E6%88%90%22%5D%0A%20%20%20%20G%20--%3E%20H%20--%3E%20I%5B%22%E4%B8%80%E4%B8%AA%E6%A8%A1%E5%9E%8B%E5%90%8C%E6%97%B6%E4%BF%9D%E7%95%99%E4%B8%A4%E8%80%85%22%5D%0A%20%20end%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<p>减法值得单独记：\\(\\theta_0+\\tau_t\\) 再减 \\(\\tau_t\\) 回到基座，摘除一个阶段的行为有明确操作。持续学习里这给了比重训便宜的回退粒度——上周期加错的向量可定向减掉；上一课适配器的「摘下即还原」对应这里的「减掉向量」，只是残差不如低秩隔离干净。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>合并的三个前提先数清。同源：向量必须出自同一基座，跨基座合并退化为蒸馏问题。成分：合并不创造能力，向量里没有的东西合成不出来。可分性：任务间改动高度重叠时，裁剪与投票会扔掉真实信号；任务数上去后干涉重新占上风，经验上十个以内可控，数十个要重新算账。</p><p>与上一课的分工：适配器隔离适合更新频繁、边界清晰的域；合并适合阶段性固化——把一串已经稳定的能力收进一个部署物。两者可叠加：合并固化历史，适配器承载增量。最后提醒一遍验收纪律：合并的每一步都可能静默亏空，没有全量探针的合并等于闭眼缝合。</p><p><span class="marginnote">初学者容易把合并想成「集齐多个模型，能力自动变多」。实际上合并只是投票与取舍：向量里没有的能力合成不出来，方向冲突的能力还会被裁决掉一部分——它守住的是已有能力，不是无中生有。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合并把序列训练换成向量组合：各阶段独立训快照，公共能力留在共享基座里不被覆盖。</li><li>TIES 三步——裁剪、投票、同号平均——把坐标冲突从数值抵消变成显式裁决；DARE 用丢弃重缩放近似。</li><li>加向量注能力、减向量摘能力，回退粒度比重训细，比适配器粗。</li><li>簿记绑定基座版本；基座一动，全部向量作废重算。</li><li>合并不创造能力、不豁免验收：合成后必须全量回归所有构成任务。</li><li>出处：Ilharco 等 2023（任务向量）；Yadav 等 2023（TIES-Merging）；Yu 等 2023（DARE）；Wortsman 等 2022（模型汤）。</li></ul>',7))])}const f=i(p,[["render",m]]);export{c as __pageData,f as default};
